 private void stopOrStart(){
  if(session==null)return;pad.cancel();
  if(!session.desktopRequested()&&session.id<0&&!session.busy){session.retryDesktop();return;}
  int controllerTask=getTaskId();session.pauseDesktop();
  // Android can bring a former external-display task onto the phone when its
  // display is removed. Keep the user's controller visible after pressing Stop.
  new Handler(Looper.getMainLooper()).postDelayed(()->{if(isFinishing()||isDestroyed()||session==null||session.desktopRequested())return;try{for(ActivityManager.AppTask task:((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getAppTasks())if(task.getTaskInfo().taskId==controllerTask){task.moveToFront();break;}}catch(RuntimeException e){session.log("Controller focus after Stop: "+e.getMessage());}},250);
 }
