 private void diagnostics(){if(session==null)return;SessionService source=session;TextView text=new TextView(this);text.setTextColor(Color.WHITE);text.setBackgroundColor(Color.rgb(18,18,18));text.setTextSize(11);text.setTypeface(Typeface.MONOSPACE);text.setTextIsSelectable(true);text.setPadding(dp(12),dp(8),dp(12),dp(8));ScrollView scroll=new ScrollView(this);scroll.addView(text);Handler handler=new Handler(Looper.getMainLooper());Runnable update=new Runnable(){public void run(){String snapshot=source.diagnosticText();if(!snapshot.contentEquals(text.getText()))text.setText(snapshot);handler.postDelayed(this,500);}};diagnosticsDialog=new AlertDialog.Builder(this).setTitle("Diagnostic log").setView(scroll).setPositiveButton("Close",null).setNeutralButton("Copy",null).setNegativeButton("Clear",null).create();diagnosticsDialog.setOnDismissListener(d->{handler.removeCallbacks(update);diagnosticsDialog=null;});diagnosticsDialog.setOnShowListener(d->{diagnosticsDialog.getButton(-3).setOnClickListener(v->{((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("DexDroid diagnostics",source.diagnosticText()));Toast.makeText(this,"Diagnostic log copied",Toast.LENGTH_SHORT).show();});diagnosticsDialog.getButton(-2).setOnClickListener(v->{source.clearDiagnostics();text.setText(source.diagnosticText());});handler.post(update);});diagnosticsDialog.show();}
